// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

/** The caller's practice deck: what to rehearse now, the most urgent first. */
export interface InterviewDeckOut {
  lang: "en" | "ur";
  roles: string[];
  /** One question for the login card; null when the caller's roles have no questions */
  question_of_the_day: InterviewQuestionOut | null;
  /** Not known first (DidNotKnow, Partly), then never rehearsed (Mandatory first), then known ones due again */
  due: InterviewQuestionOut[];
  counts: DeckCountsOut;
}

/** One PHC interview question as a list row. */
export interface InterviewQuestionOut {
  /** I-<indicator>-<requirement>, e.g. I-055-ii; C-041-a (Clinic), IIC-060-a (II C) */
  key: string;
  /** The language of the texts: the one asked for, else the caller's preference */
  lang: "en" | "ur";
  /** The manual the question comes from: I (2024), or Clinic / IIC for the questions of those manuals whose indicator has no Category I question; served only to an establishment of that category */
  framework: "I" | "Clinic" | "IIC";
  /** The indicator in its framework's manual (Category I: the 2024 revision) */
  indicator: number;
  /** The establishment's recorded PHC category (I until recorded) */
  category: "Clinic" | "IIC" | "IIB" | "IIA" | "I";
  /** The indicator's number(s) in that category's manual; empty when the category's manual has no equivalent */
  indicators_in_category: number[];
  area: string;
  /** The chapter's name in the language of the texts */
  area_name: string;
  /** A short label of the indicator in Haspataal's words (English) */
  indicator_label: string;
  /** Category I only: Mandatory = red banner in the manual, Operational = yellow; null for a question of another framework (its grade says it) */
  phc_type: "Mandatory" | "Operational" | null;
  /** Red: full compliance (Mandatory in Category I); Yellow: at least 80 % (Operational) */
  grade: "Red" | "Yellow";
  /** The compliance requirement's number in the indicator's Assessment table */
  requirement: string;
  /** As the PHC's manual words it (English) */
  requirement_text: string;
  /** The Evidence column of that row */
  evidence: ("Observation" | "Interview" | "Document Review")[];
  /** True: the manual's evidence is not Interview, but surveyors commonly ask it */
  beyond_filter: boolean;
  /** The role codes that rehearse it; all_staff = every member of staff */
  roles: string[];
  /** Whom the surveyor would usually ask (English) */
  ask: string;
  /** In the language of the texts */
  question: string;
  /** The hospital adapted the answer or the key points to its SOP (in any language) */
  adapted: boolean;
  /** False: the hospital marked it as not applicable here */
  applicable: boolean;
  not_applicable_reason: string | null;
  /** The caller's latest self-rating */
  my_rating: "Knew" | "Partly" | "DidNotKnow" | null;
  /** When the caller should rehearse it next */
  my_next_due: string | null;
}

export interface DeckCountsOut {
  /** The applicable questions of the caller's roles */
  questions: number;
  rehearsed: number;
  /** Never rehearsed, or due again today */
  due: number;
  knew: number;
  partly: number;
  did_not_know: number;
}

/** One question with everything needed to rehearse it, in the language of the texts. */
export interface InterviewQuestionDetailOut {
  /** I-<indicator>-<requirement>, e.g. I-055-ii; C-041-a (Clinic), IIC-060-a (II C) */
  key: string;
  /** The language of the texts: the one asked for, else the caller's preference */
  lang: "en" | "ur";
  /** The manual the question comes from: I (2024), or Clinic / IIC for the questions of those manuals whose indicator has no Category I question; served only to an establishment of that category */
  framework: "I" | "Clinic" | "IIC";
  /** The indicator in its framework's manual (Category I: the 2024 revision) */
  indicator: number;
  /** The establishment's recorded PHC category (I until recorded) */
  category: "Clinic" | "IIC" | "IIB" | "IIA" | "I";
  /** The indicator's number(s) in that category's manual; empty when the category's manual has no equivalent */
  indicators_in_category: number[];
  area: string;
  /** The chapter's name in the language of the texts */
  area_name: string;
  /** A short label of the indicator in Haspataal's words (English) */
  indicator_label: string;
  /** Category I only: Mandatory = red banner in the manual, Operational = yellow; null for a question of another framework (its grade says it) */
  phc_type: "Mandatory" | "Operational" | null;
  /** Red: full compliance (Mandatory in Category I); Yellow: at least 80 % (Operational) */
  grade: "Red" | "Yellow";
  /** The compliance requirement's number in the indicator's Assessment table */
  requirement: string;
  /** As the PHC's manual words it (English) */
  requirement_text: string;
  /** The Evidence column of that row */
  evidence: ("Observation" | "Interview" | "Document Review")[];
  /** True: the manual's evidence is not Interview, but surveyors commonly ask it */
  beyond_filter: boolean;
  /** The role codes that rehearse it; all_staff = every member of staff */
  roles: string[];
  /** Whom the surveyor would usually ask (English) */
  ask: string;
  /** In the language of the texts */
  question: string;
  /** The hospital adapted the answer or the key points to its SOP (in any language) */
  adapted: boolean;
  /** False: the hospital marked it as not applicable here */
  applicable: boolean;
  not_applicable_reason: string | null;
  /** The caller's latest self-rating */
  my_rating: "Knew" | "Partly" | "DidNotKnow" | null;
  /** When the caller should rehearse it next */
  my_next_due: string | null;
  /** The question in English, as an English-speaking surveyor may put it */
  question_en: string;
  /** rtl for Urdu: lay the texts out right to left */
  direction: "ltr" | "rtl";
  /** Original (English); Draft: a translation not yet reviewed by a native speaker with clinical knowledge (show it as a draft); Reviewed */
  text_status: "Original" | "Draft" | "Reviewed";
  /** Other ways the surveyor may ask the same thing */
  variants: string[];
  /** The answer to rehearse, with the hospital's facts filled in */
  model_answer: string;
  /** Hospital: adapted to the hospital's SOP in this language */
  answer_source: "Standard" | "Hospital";
  /** The bank's answer in this language with its {{placeholders}} (to adapt it) */
  standard_answer: string;
  /** What a good answer covers: the self-check and the mock interview checklist */
  key_points: string[];
  standard_key_points: string[];
  /** What the surveyor may ask next */
  follow_ups: string[];
  /** Answers that lose the point */
  pitfalls: string[];
  /** What to show the surveyor */
  show_me: string[];
  references: string[];
  facts: InterviewFactOut[];
  documents: InterviewDocumentOut[];
  /** Show under every answer: a key point not true on the ward is a gap to report */
  notice: string;
  /** The languages the hospital adapted the answer in; one of two: check the other says the same */
  adapted_languages: ("en" | "ur")[];
  hospital_version: HospitalAnswerOut | null;
}

/** A fact of the hospital the answer quotes, read live from a setting or the records. */
export interface InterviewFactOut {
  key: string;
  label: string;
  /** Null: not set yet (the answer shows a bracketed prompt instead) */
  value: string | null;
  set: boolean;
  /** Where the hospital sets it */
  where: string;
}

export interface InterviewDocumentOut {
  key: string;
  title: string;
  /** The inspection document that evidences the indicator (GET, needs its permission) */
  pdf_url: string;
}

/** The hospital's version (msds_interview_answers): null fields fall back to the bank's text in that language. */
export interface HospitalAnswerOut {
  /** English */
  model_answer: string | null;
  /** English */
  key_points: string[] | null;
  /** Urdu */
  model_answer_ur: string | null;
  /** Urdu */
  key_points_ur: string[] | null;
  /** For every language */
  applicable: boolean;
  not_applicable_reason: string | null;
  note: string | null;
  updated_by_name: string;
  updated_at: string;
  row_version: number;
}

/** How well the member of staff knew the answer, after trying it aloud and revealing the model answer. */
export interface RehearsalIn {
  /** A question's key from GET /msds/interview-prep/questions */
  question_key: string;
  /** Knew: covered every key point; Partly: some; DidNotKnow: could not answer. Sets the next rehearsal */
  rating: "Knew" | "Partly" | "DidNotKnow";
}

export interface InterviewRehearsalOut {
  rehearsal_id: number;
  question_key: string;
  rating: "Knew" | "Partly" | "DidNotKnow";
  /** Tomorrow when not known, in 3 days when partly, 7 days then doubling up to 60 when known */
  next_due: string;
  rehearsed_at: string;
  /** The caller's questions still due today */
  due_left: number;
}

/** The caller's own readiness for the surveyors' questions. */
export interface InterviewProgressOut {
  /** The language of the chapter names */
  lang: "en" | "ur";
  questions: number;
  rehearsed: number;
  knew: number;
  partly: number;
  did_not_know: number;
  /** The share of the caller's questions whose latest rating is Knew */
  ready_pct: number;
  /** Consecutive days with at least one rehearsal, up to today */
  streak_days: number;
  last_rehearsed_at: string | null;
  areas: AreaProgressOut[];
  /** The caller's latest mock interview, if any */
  last_mock_interview: MockInterviewSummaryOut | null;
}

export interface AreaProgressOut {
  area: string;
  area_name: string;
  questions: number;
  knew: number;
  partly: number;
  did_not_know: number;
  not_rehearsed: number;
}

export interface MockInterviewSummaryOut {
  mock_interview_id: number;
  interview_number: string;
  employee_id: number;
  employee_name: string;
  emp_number: string;
  role_code: string;
  role_name: string | null;
  examiner_user_id: number;
  examiner_name: string;
  held_at: string;
  note: string | null;
  questions: number;
  met: number;
  partly_met: number;
  not_met: number;
  /** Met counts 1, PartlyMet half, as a percentage of the questions */
  score_pct: number;
}

export interface InterviewRoleOut {
  /** A role code: the deck, the pocket guide and the mock interviews are per role */
  role: string;
  name: string;
  /** The questions this role rehearses for the establishment's recorded category, its own and the ones for all staff */
  questions: number;
  /** Of those, the ones written for this role (not for all staff) */
  own_questions: number;
  /** Of those, the ones of red indicators (Mandatory in Category I) */
  mandatory: number;
  /** The caller holds this role */
  mine: boolean;
}

/** A role's pocket guide as a print payload: the terminal lays it out (right to left for Urdu, with an Urdu font). */
export interface InterviewPocketGuideOut {
  lang: "en" | "ur";
  direction: "ltr" | "rtl";
  /** Draft: print a 'draft translation' mark */
  text_status: "Original" | "Draft" | "Reviewed";
  role: string;
  role_name: string;
  hospital: HospitalHeaderOut;
  title: string;
  intro: string[];
  notice: string;
  /** The two column headings: what a good answer covers, the model answer */
  columns: string[];
  footer: string;
  questions: PocketGuideQuestionOut[];
}

export interface HospitalHeaderOut {
  name: string;
  address: string;
  phone: string;
  /** The Punjab Healthcare Commission registration / licence number (GET /msds/profile); empty until an admin confirms it */
  phc_number: string;
  /** An issued document: 'Issued <when>; this copy printed <when>', with '(reprint)' an hour or more later; print it under the PHC number. Empty for a report of now */
  issue_line: string;
}

export interface PocketGuideQuestionOut {
  key: string;
  framework: "I" | "Clinic" | "IIC";
  indicator: number;
  indicators_in_category: number[];
  /** Category I only: Mandatory = red banner in the manual, Operational = yellow; null for a question of another framework (its grade says it) */
  phc_type: "Mandatory" | "Operational" | null;
  grade: "Red" | "Yellow";
  ask: string;
  question: string;
  /** The line above the question's table, in the guide's language */
  heading: string;
  key_points: string[];
  /** With the hospital's facts filled in */
  model_answer: string;
  answer_source: "Standard" | "Hospital";
}

export interface MockInterviewOut {
  mock_interview_id: number;
  interview_number: string;
  employee_id: number;
  employee_name: string;
  emp_number: string;
  role_code: string;
  role_name: string | null;
  examiner_user_id: number;
  examiner_name: string;
  held_at: string;
  note: string | null;
  questions: number;
  met: number;
  partly_met: number;
  not_met: number;
  /** Met counts 1, PartlyMet half, as a percentage of the questions */
  score_pct: number;
  /** The language of the items' questions */
  lang: "en" | "ur";
  items: MockInterviewItemOut[];
  actions: MockActionOut[];
}

export interface MockInterviewItemOut {
  item_id: number;
  question_key: string;
  question: string;
  framework: "I" | "Clinic" | "IIC";
  indicator: number;
  /** Category I only: Mandatory = red banner in the manual, Operational = yellow; null for a question of another framework (its grade says it) */
  phc_type: "Mandatory" | "Operational" | null;
  grade: "Red" | "Yellow";
  result: "Met" | "PartlyMet" | "NotMet";
  note: string | null;
}

/** A corrective action the mock interview raised (the action register, GET /quality/actions). */
export interface MockActionOut {
  action_id: number;
  action_number: string;
  action_type: "Corrective" | "Preventive";
  description: string;
  owner_name: string;
  due_date: string;
  status: "Open" | "Done" | "Cancelled";
}

/** My practice deck: the question of the day and what to rehearse now — GET /api/v1/msds/interview-prep/my-deck (who may call: holders of msds.interview.practice). */
export function myDeck(query?: { limit?: number; lang?: "en" | "ur" | null }): Promise<InterviewDeckOut> {
  return api<InterviewDeckOut>("GET", withQuery(`/msds/interview-prep/my-deck`, query), undefined);
}

/** One question: other ways of asking, the model answer with the hospital's facts, key points, follow-ups, pitfalls, what to show — GET /api/v1/msds/interview-prep/questions/{key} (who may call: holders of msds.interview.practice or msds.interview.conduct or msds.interview.manage). */
export function getQuestion(key: string, query?: { lang?: "en" | "ur" | null }): Promise<InterviewQuestionDetailOut> {
  return api<InterviewQuestionDetailOut>("GET", withQuery(`/msds/interview-prep/questions/${key}`, query), undefined);
}

/** Record how well I knew a question (Knew, Partly, DidNotKnow) — POST /api/v1/msds/interview-prep/rehearsals (who may call: holders of msds.interview.practice). */
export function rehearse(body: RehearsalIn): Promise<InterviewRehearsalOut> {
  return api<InterviewRehearsalOut>("POST", `/msds/interview-prep/rehearsals`, body, { idempotent: true });
}

/** My readiness: questions known, chapter by chapter, my streak and my last mock interview — GET /api/v1/msds/interview-prep/my-progress (who may call: holders of msds.interview.practice). */
export function myProgress(query?: { lang?: "en" | "ur" | null }): Promise<InterviewProgressOut> {
  return api<InterviewProgressOut>("GET", withQuery(`/msds/interview-prep/my-progress`, query), undefined);
}

/** The PHC inspection interview questions (filter by role, chapter, indicator, type, words) — GET /api/v1/msds/interview-prep/questions (who may call: holders of msds.interview.practice or msds.interview.conduct or msds.interview.manage). */
export function listQuestions(query?: { role?: string | null; area?: string | null; indicator?: number | null; phc_type?: "Mandatory" | "Operational" | null; search?: string | null; mine?: boolean; lang?: "en" | "ur" | null }): Promise<InterviewQuestionOut[]> {
  return api<InterviewQuestionOut[]>("GET", withQuery(`/msds/interview-prep/questions`, query), undefined);
}

/** The roles and how many inspection interview questions each rehearses — GET /api/v1/msds/interview-prep/roles (who may call: holders of msds.interview.practice or msds.interview.conduct or msds.interview.manage). */
export function rolesMsdsInterviewPrep(): Promise<InterviewRoleOut[]> {
  return api<InterviewRoleOut[]>("GET", `/msds/interview-prep/roles`, undefined);
}

/** A role's pocket guide: questions, key points and model answers (PDF) — GET /api/v1/msds/interview-prep/pocket-guide/pdf (who may call: holders of msds.interview.practice or msds.interview.conduct or msds.interview.manage). */
export function pocketGuide(query?: { role?: string | null }): Promise<unknown> {
  return api<unknown>("GET", withQuery(`/msds/interview-prep/pocket-guide/pdf`, query), undefined);
}

/** A role's pocket guide as a print payload, in English or Urdu — GET /api/v1/msds/interview-prep/pocket-guide (who may call: holders of msds.interview.practice or msds.interview.conduct or msds.interview.manage). */
export function pocketGuidePayload(query?: { role?: string | null; lang?: "en" | "ur" | null }): Promise<InterviewPocketGuideOut> {
  return api<InterviewPocketGuideOut>("GET", withQuery(`/msds/interview-prep/pocket-guide`, query), undefined);
}

/** Mock interviews, newest first (staff who do not conduct them see their own) — GET /api/v1/msds/interview-prep/mock-interviews (who may call: holders of msds.interview.practice or msds.interview.conduct or msds.interview.manage). */
export function listMocks(query?: { employee_id?: number | null; role?: string | null; limit?: number }): Promise<MockInterviewSummaryOut[]> {
  return api<MockInterviewSummaryOut[]>("GET", withQuery(`/msds/interview-prep/mock-interviews`, query), undefined);
}

/** One mock interview: each answer and the actions it raised — GET /api/v1/msds/interview-prep/mock-interviews/{mock_interview_id} (who may call: holders of msds.interview.practice or msds.interview.conduct or msds.interview.manage). */
export function getMock(mock_interview_id: number, query?: { lang?: "en" | "ur" | null }): Promise<MockInterviewOut> {
  return api<MockInterviewOut>("GET", withQuery(`/msds/interview-prep/mock-interviews/${mock_interview_id}`, query), undefined);
}
